#!/usr/bin/env bash
# Self-contained carbon report defaults initializer. MySQL 8.x, Bash, no Python.
set -euo pipefail
umask 077
write_sql() {
cat <<'__CARBON_REPORT_DEFAULTS_SQL__'
-- Carbon report defaults: self-contained, MySQL 8.x, UTF-8/LF.
-- Applies stable missing values and five reviewed default images only.
-- Existing nonempty text/valid images, uncertain defaults and reports are preserved.
-- No company/account/calculation/result/schema rows are created or modified.
-- Select the target database first. Use a fresh connection with CREATE ROUTINE privilege.
-- On any validation or write error the business-data transaction is rolled back.
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
SET SESSION sql_mode='STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';
DELIMITER //
DROP PROCEDURE IF EXISTS cr_init_report_defaults_20261019_v1//
CREATE PROCEDURE cr_init_report_defaults_20261019_v1()
SQL SECURITY INVOKER
BEGIN
    DECLARE v_n INT DEFAULT 0;
    DECLARE v_lock INT DEFAULT 0;
    DECLARE v_lock_name VARCHAR(64);
    DECLARE v_profiles_inserted INT DEFAULT 0;
    DECLARE v_profiles_updated INT DEFAULT 0;
    DECLARE v_images_inserted INT DEFAULT 0;
    DECLARE v_empty_images_archived INT DEFAULT 0;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        DROP TEMPORARY TABLE IF EXISTS tmp_cr_images;
        DROP TEMPORARY TABLE IF EXISTS tmp_cr_defaults;
        IF v_lock=1 THEN DO RELEASE_LOCK(v_lock_name); END IF;
        RESIGNAL;
    END;

    SET v_lock_name=CONCAT('cr-defaults:',LEFT(SHA2(DATABASE(),256),40));
    SELECT GET_LOCK(v_lock_name,30) INTO v_lock;
    IF COALESCE(v_lock,0)<>1 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Another report defaults initialization is running';
    END IF;

    SELECT COUNT(*) INTO v_n FROM information_schema.COLUMNS
      WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='report_dept_profile'
        AND COLUMN_NAME IN ('business_description','carbon_department','company_overview','create_by','create_time','default_accounting_method','default_activity_prose_json','default_approver','default_authors','default_chapter6_json','default_checker','default_compiler','default_equipment_json','default_exclusion_note','default_org_boundary','default_reviewer','default_validator','default_workload_json','dept_id','entity_code','header_template','id','legal_name','process_description','short_name','update_by','update_time','version');
    IF v_n <> 28 THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing report schema columns in report_dept_profile; apply code/schema migrations first';
    END IF;
    SELECT COUNT(*) INTO v_n FROM information_schema.COLUMNS
      WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='report_file'
        AND COLUMN_NAME IN ('content','create_by','create_time','default_slot','dept_id','id','kind','mime_type','object_key','original_name','report_id','role','sha256','size_bytes','snapshot_sha256','update_by','update_time');
    IF v_n <> 17 THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing report schema columns in report_file; apply code/schema migrations first';
    END IF;
    SELECT COUNT(*) INTO v_n FROM information_schema.COLUMNS
      WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='sys_dept'
        AND COLUMN_NAME IN ('del_flag','dept_id','dept_name','status');
    IF v_n <> 4 THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing report schema columns in sys_dept; apply code/schema migrations first';
    END IF;
    SELECT COUNT(*) INTO v_n FROM information_schema.COLUMNS
      WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='sys_carbon_company'
        AND COLUMN_NAME IN ('dept_id');
    IF v_n <> 1 THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing report schema columns in sys_carbon_company; apply code/schema migrations first';
    END IF;
    SELECT COUNT(*) INTO v_n FROM information_schema.TABLES
      WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('report_dept_profile','report_file') AND ENGINE='InnoDB';
    IF v_n<>2 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Report target tables must use InnoDB for atomic rollback';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.STATISTICS
        WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='report_file' AND COLUMN_NAME='default_slot' AND NON_UNIQUE=0)
      OR NOT EXISTS (SELECT 1 FROM information_schema.STATISTICS
        WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='report_dept_profile' AND COLUMN_NAME='dept_id' AND NON_UNIQUE=0)
    THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Required unique report profile/default-image indexes are missing';
    END IF;

    DROP TEMPORARY TABLE IF EXISTS tmp_cr_defaults;
    DROP TEMPORARY TABLE IF EXISTS tmp_cr_images;
    CREATE TEMPORARY TABLE tmp_cr_defaults (
      company_key VARCHAR(64) PRIMARY KEY,dept_name VARCHAR(128) NOT NULL,dept_id BIGINT NULL,
      business_description LONGTEXT NULL,
      carbon_department LONGTEXT NULL,
      company_overview LONGTEXT NULL,
      default_accounting_method LONGTEXT NULL,
      default_activity_prose_json LONGTEXT NULL,
      default_approver LONGTEXT NULL,
      default_authors LONGTEXT NULL,
      default_chapter6_json LONGTEXT NULL,
      default_checker LONGTEXT NULL,
      default_compiler LONGTEXT NULL,
      default_equipment_json LONGTEXT NULL,
      default_exclusion_note LONGTEXT NULL,
      default_org_boundary LONGTEXT NULL,
      default_reviewer LONGTEXT NULL,
      default_validator LONGTEXT NULL,
      default_workload_json LONGTEXT NULL,
      entity_code LONGTEXT NULL,
      header_template LONGTEXT NULL,
      legal_name LONGTEXT NULL,
      process_description LONGTEXT NULL,
      short_name LONGTEXT NULL
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
    CREATE TEMPORARY TABLE tmp_cr_images (
      company_key VARCHAR(64) NOT NULL,role VARCHAR(64) NOT NULL,
      original_name VARCHAR(255) NOT NULL,mime_type VARCHAR(128) NOT NULL,
      sha256 CHAR(64) NOT NULL,size_bytes BIGINT NOT NULL,content LONGBLOB NOT NULL,
      PRIMARY KEY(company_key,role)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
    INSERT INTO tmp_cr_defaults (company_key,dept_name,business_description,carbon_department,company_overview,default_accounting_method,default_activity_prose_json,default_approver,default_authors,default_chapter6_json,default_checker,default_compiler,default_equipment_json,default_exclusion_note,default_org_boundary,default_reviewer,default_validator,default_workload_json,entity_code,header_template,legal_name,process_description,short_name) VALUES (CONVERT(X'73756e696e67' USING utf8mb4),CONVERT(X'e88283e5ae81e58886e585ace58fb8' USING utf8mb4),CONVERT(X'e8b49fe8b4a3e68980e8be96e99381e8b7afe79a84e8a18ce8bda6e7bb84e7bb87efbc8ce4bba5e58f8ae5b7a5e58aa1e38081e794b5e58aa1e38081e4be9be794b5e38081e7949fe6b4bbe7ad89e8aebee5a487e8aebee696bde79a84e585bbe68aa4e7bbb4e4bfaee58f8ae7aea1e79086e38082' USING utf8mb4),'',CONVERT(X'' USING utf8mb4),CONVERT(X'e4be9de68daee3808ae99986e4b88ae8bf90e8be93e4bc81e4b89ae6b8a9e5aea4e6b094e4bd93e68e92e694bee6a0b8e7ae97e696b9e6b395e4b88ee68aa5e5918ae68c87e58d97efbc88e8af95e8a18cefbc89e3808be8bf9be8a18ce6a0b8e7ae97e38082' USING utf8mb4),CONVERT(X'7b7d' USING utf8mb4),'','',CONVERT(X'7b7d' USING utf8mb4),'','',CONVERT(X'5b5d' USING utf8mb4),'','','','',CONVERT(X'5b5d' USING utf8mb4),CONVERT(X'73756e696e67' USING utf8mb4),'',CONVERT(X'e59bbde883bde69c94e9bb84e99381e8b7afe58f91e5b195e69c89e99990e8b4a3e4bbbbe585ace58fb8e88283e5ae81e58886e585ace58fb8' USING utf8mb4),CONVERT(X'e4be9de68daee99381e8b7afe8a18ce4b89ae8bf90e8a18ce8a784e88c83e5bc80e5b195e68980e8be96e7babfe8b7afe79a84e697a5e5b8b8e4bf9de585bbe38081e6a380e4bfaeefbc8ce4bf9de99a9ce99381e8b7afe68c81e7bbade7a8b3e5ae9ae8bf90e8a18ce38082' USING utf8mb4),CONVERT(X'e88283e5ae81e58886e585ace58fb8' USING utf8mb4));
    INSERT INTO tmp_cr_images (company_key,role,original_name,mime_type,sha256,size_bytes,content) VALUES (CONVERT(X'73756e696e67' USING utf8mb4),CONVERT(X'636f7665725f6c6f676f' USING utf8mb4),CONVERT(X'636f7665725f6c6f676f2e706e67' USING utf8mb4),CONVERT(X'696d6167652f706e67' USING utf8mb4),CONVERT(X'36623537653331616236313563653461396263663536383037643731383361393939353934666635613237633237363638386433613732376334356533393438' USING utf8mb4),10016,X'');
    INSERT INTO tmp_cr_images (company_key,role,original_name,mime_type,sha256,size_bytes,content) VALUES (CONVERT(X'73756e696e67' USING utf8mb4),CONVERT(X'6f66666963655f6c6f636174696f6e' USING utf8mb4),CONVERT(X'6f66666963655f6c6f636174696f6e2e6a706567' USING utf8mb4),CONVERT(X'696d6167652f6a706567' USING utf8mb4),CONVERT(X'32363034333230346633636263396132326166313262623438643639636333626439376366393864366564346365613261376437383830373963376461376165' USING utf8mb4),220004,X'');
    INSERT INTO tmp_cr_defaults (company_key,dept_name,business_description,carbon_department,company_overview,default_accounting_method,default_activity_prose_json,default_approver,default_authors,default_chapter6_json,default_checker,default_compiler,default_equipment_json,default_exclusion_note,default_org_boundary,default_reviewer,default_validator,default_workload_json,entity_code,header_template,legal_name,process_description,short_name) VALUES (CONVERT(X'7975616e70696e67' USING utf8mb4),CONVERT(X'e58e9fe5b9b3e58886e585ace58fb8' USING utf8mb4),CONVERT(X'e8b49fe8b4a3e68980e8be96e794b5e6b094e58c96e99381e8b7afe79a84e8bf90e890a5e7bbb4e68aa4e38081e8bf90e8be93e7bb84e7bb87e5928ce5908ee58ba4e4bf9de99a9ce7aea1e79086e38082' USING utf8mb4),'',CONVERT(X'' USING utf8mb4),CONVERT(X'e4be9de68daee3808ae99986e4b88ae8bf90e8be93e4bc81e4b89ae6b8a9e5aea4e6b094e4bd93e68e92e694bee6a0b8e7ae97e696b9e6b395e4b88ee68aa5e5918ae68c87e58d97efbc88e8af95e8a18cefbc89e3808be8bf9be8a18ce6a0b8e7ae97e38082' USING utf8mb4),CONVERT(X'7b7d' USING utf8mb4),'','',CONVERT(X'7b7d' USING utf8mb4),'','',CONVERT(X'5b5d' USING utf8mb4),'','','','',CONVERT(X'5b5d' USING utf8mb4),CONVERT(X'7975616e70696e67' USING utf8mb4),'',CONVERT(X'e59bbde883bde69c94e9bb84e99381e8b7afe58f91e5b195e69c89e99990e8b4a3e4bbbbe585ace58fb8e58e9fe5b9b3e58886e585ace58fb8' USING utf8mb4),CONVERT(X'e4be9de68daee99381e8b7afe8a18ce4b89ae8bf90e8a18ce8a784e88c83e5bc80e5b195e68980e8be96e7babfe8b7afe79a84e697a5e5b8b8e4bf9de585bbe38081e6a380e4bfaeefbc8ce4bf9de99a9ce99381e8b7afe68c81e7bbade7a8b3e5ae9ae8bf90e8a18ce38082' USING utf8mb4),CONVERT(X'e58e9fe5b9b3e58886e585ace58fb8' USING utf8mb4));
    INSERT INTO tmp_cr_images (company_key,role,original_name,mime_type,sha256,size_bytes,content) VALUES (CONVERT(X'7975616e70696e67' USING utf8mb4),CONVERT(X'636f7665725f6c6f676f' USING utf8mb4),CONVERT(X'636f7665725f6c6f676f2e706e67' USING utf8mb4),CONVERT(X'696d6167652f706e67' USING utf8mb4),CONVERT(X'36623537653331616236313563653461396263663536383037643731383361393939353934666635613237633237363638386433613732376334356533393438' USING utf8mb4),10016,X'');
    INSERT INTO tmp_cr_images (company_key,role,original_name,mime_type,sha256,size_bytes,content) VALUES (CONVERT(X'7975616e70696e67' USING utf8mb4),CONVERT(X'6f66666963655f6c6f636174696f6e' USING utf8mb4),CONVERT(X'6f66666963655f6c6f636174696f6e2e6a706567' USING utf8mb4),CONVERT(X'696d6167652f6a706567' USING utf8mb4),CONVERT(X'36666262333534643766346332663862613130313964326535303766393961376236353665343338323963663831323564316463663439616566666632356462' USING utf8mb4),173620,X'');
    INSERT INTO tmp_cr_defaults (company_key,dept_name,business_description,carbon_department,company_overview,default_accounting_method,default_activity_prose_json,default_approver,default_authors,default_chapter6_json,default_checker,default_compiler,default_equipment_json,default_exclusion_note,default_org_boundary,default_reviewer,default_validator,default_workload_json,entity_code,header_template,legal_name,process_description,short_name) VALUES (CONVERT(X'6a696c69616e67' USING utf8mb4),CONVERT(X'e69cbae8be86e58886e585ace58fb8' USING utf8mb4),CONVERT(X'e689bfe68b85e99381e8b7afe8bf90e8be93e4bbbbe58aa1efbc8ce8b49fe8b4a3e79bb4e6b581e69cbae8bda6e38081e4baa4e6b581e69cbae8bda6e38081e58685e78783e69cbae8bda6e79a84e8bf90e794a8e38081e7bbb4e4bfaee7aea1e79086e4bba5e58f8ae88194e8bf90e58d95e4bd8de69cbae8bda6e8bf90e794a8e79a84e7bbbce59088e7aea1e79086e38082' USING utf8mb4),'',CONVERT(X'' USING utf8mb4),CONVERT(X'e4be9de68daee3808ae99986e4b88ae8bf90e8be93e4bc81e4b89ae6b8a9e5aea4e6b094e4bd93e68e92e694bee6a0b8e7ae97e696b9e6b395e4b88ee68aa5e5918ae68c87e58d97efbc88e8af95e8a18cefbc89e3808be8bf9be8a18ce6a0b8e7ae97e38082' USING utf8mb4),CONVERT(X'7b7d' USING utf8mb4),'','',CONVERT(X'7b7d' USING utf8mb4),'','',CONVERT(X'5b5d' USING utf8mb4),'','','','',CONVERT(X'5b5d' USING utf8mb4),CONVERT(X'6a696c69616e67' USING utf8mb4),'',CONVERT(X'e59bbde883bde69c94e9bb84e99381e8b7afe58f91e5b195e69c89e99990e8b4a3e4bbbbe585ace58fb8e69cbae8be86e58886e585ace58fb8' USING utf8mb4),CONVERT(X'e689bfe68b85e99381e8b7afe8bf90e8be93e4bbbbe58aa1efbc8ce5bc80e5b195e69cbae8bda6e8bf90e794a8e38081e7bbb4e4bfaee7aea1e79086e4bba5e58f8ae88194e8bf90e58d95e4bd8de69cbae8bda6e8bf90e794a8e79a84e7bbbce59088e7aea1e79086e38082' USING utf8mb4),CONVERT(X'e69cbae8be86e58886e585ace58fb8' USING utf8mb4));
    INSERT INTO tmp_cr_images (company_key,role,original_name,mime_type,sha256,size_bytes,content) VALUES (CONVERT(X'6a696c69616e67' USING utf8mb4),CONVERT(X'636f7665725f6c6f676f' USING utf8mb4),CONVERT(X'636f7665725f6c6f676f2e706e67' USING utf8mb4),CONVERT(X'696d6167652f706e67' USING utf8mb4),CONVERT(X'36623537653331616236313563653461396263663536383037643731383361393939353934666635613237633237363638386433613732376334356533393438' USING utf8mb4),10016,X'');
    IF EXISTS (SELECT 1 FROM tmp_cr_images WHERE size_bytes<>OCTET_LENGTH(content) OR BINARY sha256<>BINARY SHA2(content,256)) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Embedded default image checksum/length mismatch';
    END IF;

    START TRANSACTION;
    SELECT COUNT(*) INTO v_n FROM (
      SELECT s.company_key FROM tmp_cr_defaults s
      LEFT JOIN sys_dept d ON BINARY d.dept_name=BINARY s.dept_name AND d.del_flag='0' AND d.status='0'
      LEFT JOIN sys_carbon_company c ON c.dept_id=d.dept_id
      GROUP BY s.company_key HAVING COUNT(c.dept_id)<>1
    ) invalid_company;
    IF v_n<>0 THEN
      SELECT s.company_key,s.dept_name,COUNT(c.dept_id) AS active_registered_matches
      FROM tmp_cr_defaults s
      LEFT JOIN sys_dept d ON BINARY d.dept_name=BINARY s.dept_name AND d.del_flag='0' AND d.status='0'
      LEFT JOIN sys_carbon_company c ON c.dept_id=d.dept_id GROUP BY s.company_key,s.dept_name;
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Each company name must match exactly one active registered company; nothing committed';
    END IF;
    UPDATE tmp_cr_defaults s JOIN sys_dept d ON BINARY d.dept_name=BINARY s.dept_name AND d.del_flag='0' AND d.status='0'
      JOIN sys_carbon_company c ON c.dept_id=d.dept_id SET s.dept_id=d.dept_id;
    SELECT d.dept_id AS locked_company_id FROM sys_dept d JOIN tmp_cr_defaults s ON s.dept_id=d.dept_id FOR UPDATE;
    SELECT p.dept_id AS locked_profile_id FROM report_dept_profile p JOIN tmp_cr_defaults s ON s.dept_id=p.dept_id FOR UPDATE;
    SELECT f.id AS locked_default_image_id FROM report_file f JOIN tmp_cr_defaults s ON s.dept_id=f.dept_id WHERE f.kind='default' FOR UPDATE;

    IF EXISTS (SELECT 1 FROM report_dept_profile p JOIN tmp_cr_defaults s ON p.dept_id=s.dept_id
        WHERE BINARY TRIM(COALESCE(p.entity_code,'')) NOT IN (BINARY '',BINARY s.company_key,BINARY CONCAT('SH-',s.dept_id))) THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Existing company profile code conflicts with verified company identity; nothing committed';
    END IF;
    IF EXISTS (SELECT 1 FROM report_dept_profile p JOIN tmp_cr_defaults s
        ON BINARY TRIM(p.entity_code)=BINARY s.company_key AND p.dept_id<>s.dept_id) THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='A canonical company profile code belongs to another department; nothing committed';
    END IF;
    IF EXISTS (SELECT 1 FROM report_file f JOIN tmp_cr_defaults s ON f.dept_id=s.dept_id
        JOIN tmp_cr_images i ON i.company_key=s.company_key AND BINARY i.role=BINARY f.role
        WHERE f.kind='default' AND f.report_id IS NOT NULL) THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='A default image has report ownership; resolve it before initialization';
    END IF;

    INSERT INTO report_dept_profile (dept_id,business_description,carbon_department,company_overview,default_accounting_method,default_activity_prose_json,default_approver,default_authors,default_chapter6_json,default_checker,default_compiler,default_equipment_json,default_exclusion_note,default_org_boundary,default_reviewer,default_validator,default_workload_json,entity_code,header_template,legal_name,process_description,short_name,version,create_by,create_time,update_by,update_time)
      SELECT s.dept_id,s.business_description,s.carbon_department,s.company_overview,s.default_accounting_method,s.default_activity_prose_json,s.default_approver,s.default_authors,s.default_chapter6_json,s.default_checker,s.default_compiler,s.default_equipment_json,s.default_exclusion_note,s.default_org_boundary,s.default_reviewer,s.default_validator,s.default_workload_json,s.entity_code,s.header_template,s.legal_name,s.process_description,s.short_name,1,'cr-default-init-v1',NOW(),'cr-default-init-v1',NOW()
      FROM tmp_cr_defaults s LEFT JOIN report_dept_profile p ON p.dept_id=s.dept_id WHERE p.id IS NULL;
    SET v_profiles_inserted=ROW_COUNT();
    UPDATE report_dept_profile p JOIN tmp_cr_defaults s ON p.dept_id=s.dept_id
      SET p.legal_name=IF(NULLIF(TRIM(p.legal_name),'') IS NULL,s.legal_name,p.legal_name),
          p.short_name=IF(NULLIF(TRIM(p.short_name),'') IS NULL,s.short_name,p.short_name),
          p.company_overview=IF(NULLIF(TRIM(p.company_overview),'') IS NULL,s.company_overview,p.company_overview),
          p.business_description=IF(NULLIF(TRIM(p.business_description),'') IS NULL,s.business_description,p.business_description),
          p.process_description=IF(NULLIF(TRIM(p.process_description),'') IS NULL,s.process_description,p.process_description),
          p.default_accounting_method=IF(NULLIF(TRIM(p.default_accounting_method),'') IS NULL,s.default_accounting_method,p.default_accounting_method),
          p.entity_code=s.company_key,
          p.version=COALESCE(p.version,0)+1,
          p.update_by='cr-default-init-v1',
          p.update_time=NOW()
      WHERE (NULLIF(TRIM(p.legal_name),'') IS NULL) OR (NULLIF(TRIM(p.short_name),'') IS NULL) OR (NULLIF(TRIM(p.company_overview),'') IS NULL) OR (NULLIF(TRIM(p.business_description),'') IS NULL) OR (NULLIF(TRIM(p.process_description),'') IS NULL) OR (NULLIF(TRIM(p.default_accounting_method),'') IS NULL) OR (BINARY p.entity_code <> BINARY s.company_key OR p.entity_code IS NULL);
    SET v_profiles_updated=ROW_COUNT();

    -- An unusable empty placeholder is archived, retaining its ID for old references.
    UPDATE report_file f JOIN tmp_cr_defaults s ON f.dept_id=s.dept_id
      JOIN tmp_cr_images i ON i.company_key=s.company_key AND BINARY i.role=BINARY f.role
      SET f.kind='archived_default',f.update_by='cr-default-init-v1',f.update_time=NOW()
      WHERE f.kind='default' AND f.report_id IS NULL
        AND (f.content IS NULL OR OCTET_LENGTH(f.content)=0) AND NULLIF(TRIM(f.object_key),'') IS NULL;
    SET v_empty_images_archived=ROW_COUNT();
    INSERT INTO report_file (dept_id,report_id,kind,role,object_key,snapshot_sha256,
      original_name,mime_type,size_bytes,sha256,content,create_by,create_time,update_by,update_time)
      SELECT s.dept_id,NULL,'default',i.role,'','',i.original_name,i.mime_type,i.size_bytes,i.sha256,i.content,
        'cr-default-init-v1',NOW(),'cr-default-init-v1',NOW()
      FROM tmp_cr_images i JOIN tmp_cr_defaults s ON s.company_key=i.company_key
      LEFT JOIN report_file f ON f.dept_id=s.dept_id AND f.kind='default' AND BINARY f.role=BINARY i.role WHERE f.id IS NULL;
    SET v_images_inserted=ROW_COUNT();
    SELECT COUNT(*) INTO v_n FROM tmp_cr_images i JOIN tmp_cr_defaults s ON s.company_key=i.company_key
      JOIN report_file f ON f.dept_id=s.dept_id AND f.kind='default' AND BINARY f.role=BINARY i.role AND f.report_id IS NULL;
    IF v_n<>5 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Post-initialization image-slot verification failed'; END IF;
    COMMIT;

    SELECT 'REPORT_DEFAULTS_INIT_OK' AS status,DATABASE() AS target_database,
      v_profiles_inserted AS profiles_inserted,v_profiles_updated AS profiles_updated,
      v_images_inserted AS images_inserted,v_empty_images_archived AS empty_images_archived;
    SELECT s.company_key,p.dept_id,d.dept_name,p.entity_code,p.version,
      (NULLIF(TRIM(p.company_overview),'') IS NOT NULL) AS has_overview,
      (NULLIF(TRIM(p.business_description),'') IS NOT NULL) AS has_business,
      (NULLIF(TRIM(p.process_description),'') IS NOT NULL) AS has_process
      FROM tmp_cr_defaults s JOIN report_dept_profile p ON p.dept_id=s.dept_id JOIN sys_dept d ON d.dept_id=s.dept_id ORDER BY s.company_key;
    SELECT s.company_key,f.id,f.role,OCTET_LENGTH(f.content) AS content_bytes,f.sha256,
      CASE WHEN f.content=i.content AND BINARY f.sha256=BINARY i.sha256 THEN 'REVIEWED_DEFAULT_OK'
           WHEN OCTET_LENGTH(f.content)>0 AND LOWER(f.sha256)=SHA2(f.content,256) THEN 'EXISTING_IMAGE_KEPT'
           WHEN (f.content IS NULL OR OCTET_LENGTH(f.content)=0) AND NULLIF(TRIM(f.object_key),'') IS NOT NULL THEN 'LEGACY_OBJECT_REFERENCE_CHECK'
           ELSE 'EXISTING_IMAGE_NEEDS_CHECK' END AS image_status
      FROM tmp_cr_images i JOIN tmp_cr_defaults s ON s.company_key=i.company_key
      JOIN report_file f ON f.dept_id=s.dept_id AND f.kind='default' AND BINARY f.role=BINARY i.role ORDER BY s.company_key,f.role;
    DROP TEMPORARY TABLE tmp_cr_images;
    DROP TEMPORARY TABLE tmp_cr_defaults;
    DO RELEASE_LOCK(v_lock_name);
END//
CALL cr_init_report_defaults_20261019_v1()//
DROP PROCEDURE cr_init_report_defaults_20261019_v1//
DELIMITER ;
__CARBON_REPORT_DEFAULTS_SQL__
}
usage() {
  cat <<'USAGE'
Usage:
  bash init_report_defaults.sh --container MYSQL_CONTAINER [--database carbon_emissions] [--user root] [--backup-dir PATH]
  bash init_report_defaults.sh --local [--host 127.0.0.1] [--port 3306] [--database carbon_emissions] [--user root] [--backup-dir PATH]
The script prompts for the database password. No password is accepted on the command line.
It backs up profiles and existing default images, then initializes stable missing defaults.
Use --container for a Docker database, --local for a host/remote MySQL client connection.
USAGE
}
mode=''; container=''; database='carbon_emissions'; db_user='root'; db_host='127.0.0.1'; db_port='3306'; backup_dir=''
while (($#)); do
  case "$1" in
    --container) [[ $# -ge 2 ]] || { usage; exit 2; }; mode='docker'; container=$2; shift 2;;
    --local) mode='local'; shift;;
    --database) [[ $# -ge 2 ]] || { usage; exit 2; }; database=$2; shift 2;;
    --user) [[ $# -ge 2 ]] || { usage; exit 2; }; db_user=$2; shift 2;;
    --host) [[ $# -ge 2 ]] || { usage; exit 2; }; db_host=$2; shift 2;;
    --port) [[ $# -ge 2 ]] || { usage; exit 2; }; db_port=$2; shift 2;;
    --backup-dir) [[ $# -ge 2 ]] || { usage; exit 2; }; backup_dir=$2; shift 2;;
    --help|-h) usage; exit 0;;
    *) printf 'Unknown argument: %s\n' "$1" >&2; usage; exit 2;;
  esac
done
[[ $mode == docker || $mode == local ]] || { usage; exit 2; }
[[ $database =~ ^[a-zA-Z0-9_]+$ ]] || { echo 'Invalid database name' >&2; exit 2; }
[[ $db_user =~ ^[a-zA-Z0-9_.@-]+$ ]] || { echo 'Invalid database user name' >&2; exit 2; }
[[ $db_port =~ ^[0-9]+$ ]] || { echo 'Invalid port' >&2; exit 2; }
if [[ $mode == docker ]]; then
  [[ $container =~ ^[a-zA-Z0-9_.-]+$ ]] || { echo 'Invalid container name' >&2; exit 2; }
  command -v docker >/dev/null || { echo 'docker is unavailable' >&2; exit 2; }
  [[ $(docker inspect --format '{{.State.Running}}' "$container") == true ]] || { echo 'Database container is not running' >&2; exit 2; }
else
  command -v mysql >/dev/null || { echo 'mysql client is unavailable' >&2; exit 2; }
  command -v mysqldump >/dev/null || { echo 'mysqldump is unavailable' >&2; exit 2; }
fi
work_dir=$(mktemp -d "${TMPDIR:-/tmp}/carbon-report-init.XXXXXXXX")
local_cnf="$work_dir/client.cnf"; local_sql="$work_dir/defaults.sql"
remote_cnf="/tmp/carbon-report-init-$(date +%Y%m%d%H%M%S)-$$.cnf"
cleanup() {
  if [[ $mode == docker ]]; then docker exec -u 0 "$container" rm -f "$remote_cnf" >/dev/null 2>&1 || true; fi
  rm -f "$local_cnf" "$local_sql"
  rmdir "$work_dir" >/dev/null 2>&1 || true
}
trap cleanup EXIT
trap 'exit 130' INT
trap 'exit 143' TERM
printf 'Target: mode=%s database=%s user=%s container=%s\n' "$mode" "$database" "$db_user" "${container:-host-client}"
read -r -s -p 'Database password: ' db_password
printf '\n'
escaped=${db_password//\\/\\\\}; escaped=${escaped//\"/\\\"}
printf '[client]\nuser=%s\npassword="%s"\ndefault-character-set=utf8mb4\n' "$db_user" "$escaped" > "$local_cnf"
unset db_password escaped
chmod 600 "$local_cnf"
write_sql > "$local_sql"
if [[ $mode == docker ]]; then
  docker cp "$local_cnf" "$container:$remote_cnf" >/dev/null
  docker exec -u 0 "$container" chmod 600 "$remote_cnf"
fi
run_client() {
  local executable=$1; shift
  if [[ $mode == docker ]]; then
    docker exec -u 0 -i "$container" "$executable" --defaults-extra-file="$remote_cnf" "$@"
  else
    "$executable" --defaults-extra-file="$local_cnf" --host="$db_host" --port="$db_port" "$@"
  fi
}
run_client mysql --batch --skip-column-names --database="$database" --execute='SELECT VERSION(),DATABASE();'
if [[ -z $backup_dir ]]; then backup_dir="$(pwd)/report-defaults-backup-$(date +%Y%m%d-%H%M%S)-$$"; fi
mkdir -p "$backup_dir"
chmod 700 "$backup_dir"
dump_opts=(--single-transaction --skip-lock-tables --no-create-info --skip-triggers --skip-add-locks --skip-disable-keys --complete-insert --hex-blob --no-tablespaces --set-gtid-purged=OFF)
run_client mysqldump "${dump_opts[@]}" "$database" report_dept_profile > "$backup_dir/profiles.before.sql"
run_client mysqldump "${dump_opts[@]}" --where="kind='default'" "$database" report_file > "$backup_dir/default-images.before.sql"
echo 'Backups saved. Applying report defaults transaction...'
run_client mysql --batch --database="$database" < "$local_sql" | tee "$backup_dir/initialization.log"
grep -q '^REPORT_DEFAULTS_INIT_OK' "$backup_dir/initialization.log" || { echo 'Success marker missing: inspect initialization.log' >&2; exit 1; }
printf 'Completed. Private backup and log directory: %s\n' "$backup_dir"
